fn heat(v: i32) -> i32 {
    let r: i32 = v * 255 / 99;
    let b: i32 = 255 - r;
    r * 65536 + 40 * 256 + b
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x000000);
    let cw: i32 = (w - 80) / 12;
    let ch: i32 = (h - 40) / 8;
    let mut y: i32 = 0;
    while y < 8 {
        let mut x: i32 = 0;
        while x < 12 {
            let v: i32 = (x * x + y * y) * 99 / 170;
            host::display::fill_rect(12 + x * cw, 20 + y * ch, cw - 2, ch - 2, heat(v));
            x = x + 1;
        }
        y = y + 1;
    }
    let sx: i32 = w - 52;
    let mut k: i32 = 0;
    while k < 8 {
        host::display::fill_rect(sx, 20 + k * ch, 16, ch, heat(99 - k * 99 / 7));
        k = k + 1;
    }
    host::display::draw_number(sx + 22, 20, 99, 0xc0c0c0, 1);
    host::display::draw_number(sx + 22, 20 + 7 * ch, 0, 0xc0c0c0, 1);
    host::display::present();
}
